let authUser=null,csrfToken="",personalQueue=Promise.resolve();async function api(url,method="GET",data){const r=await fetch(url,{method,credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":csrfToken},body:data===void 0?void 0:JSON.stringify(data)}),b=await r.json();if(!r.ok)throw r.status===401&&authUser&&(authUser=null,CafasGPS.pause(),showLogin("Tu sesi\xF3n ha terminado. Ingresa nuevamente.")),Error(b.error||"No se pudo completar la operaci\xF3n.");return b}function showLogin(message=""){document.body.classList.add("auth-loading"),$("#authScreen").hidden=!1,$("#content").innerHTML="",$("#authScreen").innerHTML=`<section class="login-card"><span class="eyebrow">CAFAS \xB7 ACCESO PERSONAL</span><h1>Tu preparaci\xF3n<br>empieza aqu\xED.</h1><p>Ingresa con tu c\xE9dula y contrase\xF1a.</p><form onsubmit="login(event)"><label>C\xE9dula<input name="document" inputmode="numeric" autocomplete="username" required pattern="[0-9]{4,20}"></label><label>Contrase\xF1a<input name="password" type="password" autocomplete="current-password" required maxlength="200"></label><p id="loginError" role="alert">${esc(message)}</p><button class="btn" type="submit">INGRESAR \u2197</button></form></section>`}async function login(event){event.preventDefault();const button=event.target.querySelector("button");button.disabled=!0;try{const data=Object.fromEntries(new FormData(event.target));await activate(await api("/api/login","POST",data))}catch(e){$("#loginError").textContent=e.message,button.disabled=!1}}async function activate(result){authUser=result.user,csrfToken=result.csrf,activeUser={...authUser,role:authUser.canEvaluate?"evaluator":"evaluated"},selectedDoc=null,draft=null,resultFilters.clear(),await refreshFlow();const personal=await api("/api/personal");state.activities=personal.activities,state.profile={...authUser},state.evaluations=[],CafasGPS.restore(personal.routes),$("#authScreen").hidden=!0,document.body.classList.remove("auth-loading"),go("home")}async function refreshFlow(){flow=await api("/api/state");const self=flow.people.find(p=>p.document===authUser.document);self&&(authUser={...authUser,...self},activeUser={...activeUser,...self},state.profile={...self})}async function refreshPage(){try{if(draft){notify("Guarda o cancela el borrador antes de actualizar.");return}await refreshFlow(),go(current)}catch(e){notify(e.message)}}async function switchRole(role){if(!(!authUser.canEvaluate||!["evaluator","evaluated"].includes(role))){if(draft?.results.length&&!confirm("\xBFDescartar la prueba sin guardar?")){go(current);return}draft=null,selectedDoc=null,activeUser={...authUser,role},await refreshPage()}}async function logout(){if(!(draft?.results.length&&!confirm("\xBFCerrar sesi\xF3n y descartar la prueba sin guardar?")))try{CafasGPS.pause(),await personalQueue,await api("/api/logout","POST",{}),location.reload()}catch(e){notify(e.message)}}function savePersonal(){const payload={activities:state.activities,routes:CafasGPS.getRoutes()},snapshot=JSON.parse(JSON.stringify(payload));return personalQueue=personalQueue.catch(()=>{}).then(()=>api("/api/personal","PUT",snapshot)),personalQueue.catch(e=>notify("No se sincroniz\xF3 la actividad: "+e.message)),personalQueue}saveActivity=async function(event){event.preventDefault();const f=new FormData(event.target),button=event.target.querySelector("[type=submit]");button.disabled=!0;const record={type:f.get("type"),date:f.get("date"),duration:Number(f.get("duration")),distance:Number(f.get("distance"))};state.activities.push(record);try{await persist(),closeModal(),go(current),notify("Actividad guardada en tu cuenta.")}catch(e){state.activities=state.activities.filter(a=>a!==record),button.disabled=!1,notify(e.message)}},render.profile=()=>{const p=flow.people.find(p2=>p2.document===authUser.document);return head("MI PERFIL",esc(p.name),"Datos vinculados a tu c\xE9dula de ciudadan\xEDa.")+`<div class="layout"><section class="panel"><h2>Mis datos</h2><p>C\xE9dula: ${esc(p.document)} \xB7 ${p.sex==="H"?"Hombre":"Mujer"}</p><p>Roles: ${authUser.canEvaluate?"Evaluador y evaluado":"Evaluado"}</p><form onsubmit="saveMeasurements(event)"><div class="formgrid"><label>Edad cumplida<input name="age" type="number" min="17" max="100" step="1" value="${p.age??""}" required></label><label>Estatura (cm)<input name="height" type="number" min="100" max="230" step="0.1" value="${p.height??""}" required></label><label>Peso (kg)<input name="weight" type="number" min="30" max="250" step="0.1" value="${p.weight??""}" required></label></div><button class="btn">Guardar datos</button></form></section><section class="panel"><h2>Cambiar contrase\xF1a</h2><form onsubmit="changePassword(event)"><label>Contrase\xF1a actual<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="200"></label><label>Nueva contrase\xF1a<input name="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><p class="muted">M\xEDnimo 10 caracteres, diferente de tu c\xE9dula.</p><button class="btn outline">Actualizar contrase\xF1a</button></form></section></div>`};async function saveMeasurements(event){event.preventDefault();try{const b=Object.fromEntries([...new FormData(event.target)].map(([k,v])=>[k,Number(v)]));await api("/api/users/"+authUser.document+"/measurements","PATCH",b),await refreshFlow(),go("profile"),notify("Datos actualizados.")}catch(e){notify(e.message)}}async function changePassword(event){event.preventDefault();try{await api("/api/password","POST",Object.fromEntries(new FormData(event.target))),event.target.reset(),notify("Contrase\xF1a actualizada. Las otras sesiones se cerraron.")}catch(e){notify(e.message)}}(async()=>{try{await activate(await api("/api/me"))}catch{authUser=null,showLogin()}})();
